/* @autogenerated */
package net.civeira.phylax.feature.observe.ingest;

import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;

import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.SpanContext;

/**
 * java.util.logging handler (JBoss LogManager in Quarkus) that queues the logs of this process. The
 * loggers of the observability itself and the "traces" logger (one line per span of
 * LoggingSpanExporter) are skipped, to avoid loops and duplicates.
 */
public class ObserveLogHandler extends Handler {

  private final TelemetryMapper mapper;
  private final ObservePipeline pipeline;
  private final String ownPackage;

  public ObserveLogHandler(final TelemetryMapper mapper, final ObservePipeline pipeline) {
    this.mapper = mapper;
    this.pipeline = pipeline;
    this.ownPackage = ObserveLogHandler.class.getPackageName().substring(0,
        ObserveLogHandler.class.getPackageName().lastIndexOf('.'));
    setLevel(Level.ALL);
  }

  @Override
  public void publish(final LogRecord record) {
    String logger = record.getLoggerName();
    if (null == logger || logger.startsWith(ownPackage) || "traces".equals(logger)) {
      return;
    }
    String message = record.getMessage();
    if (null != record.getParameters() && record.getParameters().length > 0 && null != message) {
      try {
        message =
            message.contains("{0") ? java.text.MessageFormat.format(message, record.getParameters())
                : String.format(message.replace("{}", "%s"), record.getParameters());
      } catch (RuntimeException ex) {
        // Keep the raw message
      }
    }
    SpanContext span = Span.current().getSpanContext();
    String traceId = span.isValid() ? span.getTraceId() : null;
    String spanId = span.isValid() ? span.getSpanId() : null;
    java.util.Map<String, String> mdc =
        record instanceof org.jboss.logmanager.ExtLogRecord ext ? ext.getMdcCopy()
            : java.util.Map.of();
    mapper.ownLog(record.getMillis(), record.getLevel().getName(), logger, message,
        record.getThrown(), traceId, spanId, mdc).ifPresent(pipeline::offer);
  }

  @Override
  public void flush() {
    // Nothing: the pipeline writes asynchronously
  }

  @Override
  public void close() {
    // Nothing
  }
}
